--changeset luudong:272-pham-vi-quan-tri-vien
--comment Quản trị viên chỉ làm phần hệ thống và danh mục theo tài liệu G123 (HT-04, HT-05, DM-01..04, TC-01, cùng các UC chung: tổng hợp, báo cáo, tra cứu thiết bị). Thu quyền lập / duyệt / xoá phiếu nghiệp vụ, sửa thiết bị, phòng và nhập dữ liệu đầu vào; cổng Admin cũng không ghi các tài nguyên này (PortalRoutes.BUSINESS_DATA).
DELETE FROM role_permissions rp
USING roles r, permissions p
WHERE rp.role_id = r.id AND rp.permission_id = p.id AND r.code = 'ADMIN'
  AND p.code IN ('equipment:write', 'equipment:delete', 'data_imports:read', 'data_imports:write', 'data_imports:delete', 'rooms:write', 'rooms:delete', 'purchase_proposals:read', 'purchase_proposals:write', 'purchase_proposals:delete', 'purchase_proposals:approve', 'purchase_proposals:export', 'procurement_plans:read', 'procurement_plans:write', 'procurement_plans:delete', 'procurement_plans:approve', 'procurement_plans:export', 'equipment_intakes:read', 'equipment_intakes:write', 'equipment_intakes:delete', 'equipment_intakes:approve', 'equipment_intakes:export', 'inventory_campaigns:read', 'inventory_campaigns:write', 'inventory_campaigns:delete', 'inventory_sessions:read', 'inventory_sessions:write', 'inventory_sessions:delete', 'inventory_sessions:approve', 'inventory_sessions:export');
--rollback INSERT INTO role_permissions (role_id, permission_id) SELECT r.id, p.id FROM roles r, permissions p WHERE r.code = 'ADMIN' AND p.code IN ('equipment:write', 'equipment:delete', 'data_imports:read', 'data_imports:write', 'data_imports:delete', 'rooms:write', 'rooms:delete', 'purchase_proposals:read', 'purchase_proposals:write', 'purchase_proposals:delete', 'purchase_proposals:approve', 'purchase_proposals:export', 'procurement_plans:read', 'procurement_plans:write', 'procurement_plans:delete', 'procurement_plans:approve', 'procurement_plans:export', 'equipment_intakes:read', 'equipment_intakes:write', 'equipment_intakes:delete', 'equipment_intakes:approve', 'equipment_intakes:export', 'inventory_campaigns:read', 'inventory_campaigns:write', 'inventory_campaigns:delete', 'inventory_sessions:read', 'inventory_sessions:write', 'inventory_sessions:delete', 'inventory_sessions:approve', 'inventory_sessions:export') ON CONFLICT DO NOTHING;
